import numpy as np
import mujoco
from scipy.spatial.transform import Rotation
from rcb_kinder import Session
class Controller:
 def __init__(self):
  self.s=Session(); self.m=self.s.model; self.d=mujoco.MjData(self.m); self.site=self.m.site('robot_pinch_site').id
  self.qa=np.arange(45,52); self.va=np.array([self.m.jnt_dofadr[self.m.joint('robot_joint_'+str(i)).id] for i in range(1,8)])
  self.actions=[]; self.grip=0; self.success=False
 def pose(self): return self.s.data.site_xpos[self.site].copy(),self.s.data.site_xmat[self.site].reshape(3,3).copy()
 def obj(self,i):
  b=self.m.body('cuboid_'+str(i)).id
  return self.s.data.xpos[b].copy(),self.s.data.xmat[b].reshape(3,3).copy()
 def ik(self,p,R,base=None):
  self.d.qpos[:]=self.s.data.qpos; self.d.qvel[:]=0
  if base is not None:self.d.qpos[42:45]=base
  jp=np.zeros((3,self.m.nv)); jr=jp.copy()
  for _ in range(100):
   mujoco.mj_kinematics(self.m,self.d);mujoco.mj_comPos(self.m,self.d)
   cur=self.d.site_xmat[self.site].reshape(3,3)
   err=np.r_[np.asarray(p)-self.d.site_xpos[self.site],Rotation.from_matrix(R@cur.T).as_rotvec()]
   if np.linalg.norm(err)<1e-5:break
   mujoco.mj_jacSite(self.m,self.d,jp,jr,self.site)
   J=np.vstack([jp[:,self.va],jr[:,self.va]])
   dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*.0001,err)
   self.d.qpos[self.qa]+=np.clip(dq,-.15,.15)
   for k in [1,3,5]:self.d.qpos[45+k]=np.clip(self.d.qpos[45+k],self.m.jnt_range[9+k,0]+.001,self.m.jnt_range[9+k,1]-.001)
  return self.d.qpos[self.qa].copy(),np.linalg.norm(err)
 def step(self,a):
  if self.success:return
  if self.s.t>=1000:raise RuntimeError('budget')
  _,self.success,_=self.s.step(a);self.actions.append(np.array(a))
 def hold(self,n):
  for _ in range(n):self.step(np.r_[np.zeros(10),self.grip])
 def move(self,p,R=None,base=None,n=30):
  if R is None:R=self.pose()[1]
  if base is None:base=self.s.data.qpos[42:45].copy()
  q,err=self.ik(p,R,base)
  print('move',self.s.t,'p',np.round(p,3),'IK',round(err,5),flush=True)
  for k in range(n):
   a=np.r_[np.clip(np.asarray(base)-self.s.data.qpos[42:45],-.07,.07),np.clip(q-self.s.data.qpos[self.qa],-.1,.1),self.grip]
   self.step(a)
  print('end',self.s.t,'ee',np.round(self.pose()[0],3),flush=True)
 def save(self):self.s.save_trajectory(self.actions,'/app/output/trajectory.npz')
 def photo(self,path):
  from PIL import Image
  Image.fromarray(self.s.images(['task_view'])['task_view']).save(path)
def top(R):return R@np.diag([1,-1,-1])
PLACE=np.array([[0,0,1],[1,0,0],[0,1,0.]])
PY
